import React, { useEffect, useState, useRef } from "react";
import { Link } from "react-router-dom";

const Navbar = () => {
  const [user, setUser] = useState(null);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef();

  // Get user from localStorage
  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem("user"));
    setUser(storedUser);
  }, []);

  // Close dropdown if clicked outside
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("user");
    window.location.reload();
  };

  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        padding: "18px 50px",
        background: "linear-gradient(90deg, #ffd6ec, #d6faff)",
        boxShadow: "0 5px 20px rgba(0,0,0,0.08)",
        position: "sticky",
        top: "0",
        zIndex: "1000",
      }}
    >
      <h2 style={{ color: "#ff4f87", margin: 0 }}>Nanhe Farishte</h2>

      <div style={{ display: "flex", gap: "15px", alignItems: "center" }}>
        <NavButton to="/">Home</NavButton>
        <NavButton to="/products">Products</NavButton>
        <NavButton to="/about">About</NavButton>
        <NavButton to="/contact">Contact</NavButton>

        {user ? (
          <div style={{ position: "relative" }} ref={dropdownRef}>
            {/* Avatar */}
            <img
              src="https://www.svgrepo.com/show/452117/user-profile.svg" // gray generic avatar
              alt="avatar"
              style={{
                width: "40px",
                height: "40px",
                borderRadius: "50%",
                cursor: "pointer",
                border: "2px solid #ccc",
              }}
              onClick={() => setDropdownOpen(!dropdownOpen)}
            />

            {/* Dropdown */}
            {dropdownOpen && (
              <div
                style={{
                  position: "absolute",
                  top: "50px",
                  right: "0",
                  background: "white",
                  boxShadow: "0 4px 12px rgba(0,0,0,0.15)",
                  borderRadius: "8px",
                  padding: "10px",
                  minWidth: "150px",
                  zIndex: "100",
                }}
              >
                <p style={{ margin: "5px 0", fontWeight: "600" }}>{user.name}</p>
                <button
                  onClick={handleLogout}
                  style={{
                    background: "#ff4f87",
                    border: "none",
                    padding: "6px 12px",
                    borderRadius: "5px",
                    color: "white",
                    cursor: "pointer",
                    fontWeight: "500",
                  }}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        ) : (
          <NavButton to="/login">Login</NavButton>
        )}
      </div>

      {/* CART */}
      <Link to="/cart" style={{ textDecoration: "none" }}>
        <button
          style={{
            background: "#ff4f87",
            border: "none",
            padding: "10px 20px",
            borderRadius: "25px",
            color: "white",
            cursor: "pointer",
            fontWeight: "600",
          }}
        >
          🛒 Cart
        </button>
      </Link>
    </div>
  );
};

const NavButton = ({ to, children }) => {
  return (
    <Link to={to} style={{ textDecoration: "none" }}>
      <button
        style={{
          background: "white",
          border: "none",
          padding: "8px 18px",
          borderRadius: "20px",
          cursor: "pointer",
          fontWeight: "500",
          color: "#444",
          transition: "0.3s",
        }}
        onMouseOver={(e) => {
          e.target.style.background = "#ff4f87";
          e.target.style.color = "white";
        }}
        onMouseOut={(e) => {
          e.target.style.background = "white";
          e.target.style.color = "#444";
        }}
      >
        {children}
      </button>
    </Link>
  );
};

export default Navbar;
